export async function listTools() {
  return [
    {
      name: 'open_client',
      description: 'Open a client with its own independent key/value map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Non-empty unique client identifier.' }
        },
        required: ['client_id']
      }
    },
