      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' },
          value: { type: 'string' }
        },
        required: ['client_id', 'key', 'value']
      }
    },
    {
      name: 'client_get',
      description: 'Read a key from the given client map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' }
        },
        required: ['client_id', 'key']
      }
    }
  ];
}

function requireString(args, name) {
  const v = args[name];
  if (typeof v !== 'string' || v.length === 0) {
    throw new Error(`${name} must be a non-empty string`);
  }
  return v;
}

export async function callTool(name, args = {}) {
  if (name === 'open_client') {
    const client_id = requireString(args, 'client_id');
    if (!clients.has(client_id)) {
      clients.set(client_id, new Map());
    }
    return { content: [{ type: 'text', text: `client ${client_id} opened` }] };
  }
  if (name === 'client_put') {
    const client_id = requireString(args, 'client_id');
    const key = requireString(args, 'key');
    const value = requireString(args, 'value');
    const store = clients.get(client_id);
    if (!store) {
      throw new Error(`unknown client: ${client_id}`);
    }
    store.set(key, value);
    return { content: [{ type: 'text', text: `ok` }] };
  }
  if (name === 'client_get') {
    const client_id = requireString(args, 'client_id');
    const key = requireString(args, 'key');
    const store = clients.get(client_id);
    if (!store) {
      throw new Error(`unknown client: ${client_id}`);
    }
    if (!store.has(key)) {
      throw new Error(`unknown key: ${key}`);
    }
    return { content: [{ type: 'text', text: store.get(key) }] };
  }
  throw new Error(`unknown tool: ${name}`);
}
```

